/*
 * asound.c - libasound.so.2 for the guest: the sound card is the host's.
 *
 * There is no sound device in the kernel gx runs, and the real ALSA library
 * would look for one. This one has the part of ALSA a program uses to play
 * sound (streams of two channels of 16 bits, the way Chromium asks for them,
 * which the host mixes) and gives the samples to the host, through the
 * functions gx_audio_stream_* that
 * hostlib.c binds (see GX_LIST). Everything else ALSA has says that there is
 * nothing: no card, no mixer, no MIDI. Those are generated by the build from
 * what the program imports (see build-chromium.sh); only what plays is here.
 */
#include <errno.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>

/* The host's (hostlib.c makes them): frames are two samples of 16 bits, and
 * a stream is the number the host gives it. */
long gx_audio_stream_open(long rate, long channels);            /* -1: none */
long gx_audio_stream_write(long id, const void *frames, long count);   /* frames taken */
long gx_audio_stream_queued(long id);                           /* frames not played yet */
void gx_audio_stream_drop(long id);
void gx_audio_stream_close(long id);

#define FORMAT_S16_LE 2
#define STATE_PREPARED 2
#define STATE_RUNNING 3

struct pcm {
	int configured, running;
	unsigned channels;      /* the program's; the host gets two */
	long id, rate, buffer, period;
};

int snd_pcm_open(struct pcm **pcm, const char *name, int stream, int mode)
{
	struct pcm *p;

	(void)name;
	(void)mode;
	/* Playback only. Several at once (a page's WebAudio and its <audio>,
	 * each a stream of Chromium's): the host mixes them. With one only,
	 * the second was refused and played nothing. */
	if (stream != 0)
		return -ENOENT;
	p = calloc(1, sizeof(*p));
	if (!p)
		return -ENOMEM;
	p->id = -1;
	*pcm = p;
	return 0;
}

int snd_pcm_close(struct pcm *pcm)
{
	if (pcm->configured)
		gx_audio_stream_close(pcm->id);
	free(pcm);
	return 0;
}

int snd_pcm_set_params(struct pcm *pcm, int format, int access, unsigned channels, unsigned rate,
		       int soft_resample, unsigned latency_us)
{
	(void)access;
	(void)soft_resample;
	/* The host plays two channels. A program may ask for one (Chromium
	 * does for a mono file: a Discord voice message) or more: refused,
	 * Chromium played it to nothing, as if it were heard. Mono is played
	 * on both sides; of more, the first two (front left and right). */
	if (format != FORMAT_S16_LE || channels < 1 || channels > 8)
		return -EINVAL;
	pcm->channels = channels;
	if (!pcm->configured && (pcm->id = gx_audio_stream_open(rate, 2)) < 0)
		return -EBUSY;
	pcm->configured = 1;
	pcm->rate = rate;
	pcm->buffer = (long)((uint64_t)latency_us * rate / 1000000);
	if (pcm->buffer < 1024)
		pcm->buffer = 1024;
	pcm->period = pcm->buffer / 4;
	return 0;
}

int snd_pcm_get_params(struct pcm *pcm, unsigned long *buffer_size, unsigned long *period_size)
{
	*buffer_size = pcm->buffer;
	*period_size = pcm->period;
	return 0;
}

long snd_pcm_avail_update(struct pcm *pcm)
{
	long room = pcm->buffer - gx_audio_stream_queued(pcm->id);

	return room < 0 ? 0 : room;
}

int snd_pcm_delay(struct pcm *pcm, long *delay)
{
	*delay = gx_audio_stream_queued(pcm->id);
	return 0;
}

long snd_pcm_writei(struct pcm *pcm, const void *frames, unsigned long count)
{
	long room = snd_pcm_avail_update(pcm), done;

	if (!pcm->configured)
		return -EBADFD;
	if ((long)count > room)
		count = room;
	if (!count)
		return -EAGAIN;
	if (pcm->channels == 2) {
		done = gx_audio_stream_write(pcm->id, frames, count);
	} else {
		/* In pieces, made two channels. */
		const int16_t *in = frames;
		int16_t stereo[1024 * 2];
		unsigned long piece = count > 1024 ? 1024 : count;

		for (unsigned long i = 0; i < piece; i++) {
			const int16_t *f = in + i * pcm->channels;

			stereo[i * 2] = f[0];
			stereo[i * 2 + 1] = pcm->channels == 1 ? f[0] : f[1];
		}
		done = gx_audio_stream_write(pcm->id, stereo, piece);
	}
	if (done <= 0)
		return -EAGAIN;
	pcm->running = 1;
	return done;
}

long snd_pcm_readi(struct pcm *pcm, void *frames, unsigned long count)
{
	(void)pcm;
	(void)frames;
	(void)count;
	return -EBADFD;
}

int snd_pcm_state(struct pcm *pcm)
{
	return pcm->running ? STATE_RUNNING : STATE_PREPARED;
}

int snd_pcm_prepare(struct pcm *pcm)
{
	pcm->running = 0;
	return 0;
}

int snd_pcm_start(struct pcm *pcm)
{
	pcm->running = 1;
	return 0;
}

int snd_pcm_drop(struct pcm *pcm)
{
	if (pcm->configured)
		gx_audio_stream_drop(pcm->id);
	pcm->running = 0;
	return 0;
}

int snd_pcm_drain(struct pcm *pcm)
{
	(void)pcm;
	return 0;
}

int snd_pcm_resume(struct pcm *pcm)
{
	(void)pcm;
	return 0;
}

int snd_pcm_recover(struct pcm *pcm, int err, int silent)
{
	(void)pcm;
	(void)silent;
	return err == -EAGAIN ? err : 0;
}

const char *snd_pcm_name(struct pcm *pcm)
{
	(void)pcm;
	return "default";
}

long snd_pcm_format_size(int format, unsigned long samples)
{
	return format == FORMAT_S16_LE ? (long)samples * 2 : -EINVAL;
}

const char *snd_strerror(int err)
{
	return strerror(err < 0 ? -err : err);
}

/* One card, with one device on it that plays: "default", the name programs
 * open when they have no reason to open another. */
int snd_card_next(int *card)
{
	*card = *card < 0 ? 0 : -1;
	return 0;
}

int snd_device_name_hint(int card, const char *iface, void ***hints)
{
	static char device[] = "default";

	(void)iface;
	*hints = calloc(2, sizeof(void *));
	if (!*hints)
		return -ENOMEM;
	if (card <= 0)
		(*hints)[0] = device;
	return 0;
}

/* The answers are the caller's to free. */
char *snd_device_name_get_hint(const void *hint, const char *id)
{
	(void)hint;
	if (!strcmp(id, "NAME"))
		return strdup("default");
	if (!strcmp(id, "DESC"))
		return strdup("Console");
	if (!strcmp(id, "IOID"))
		return strdup("Output");
	return NULL;
}

int snd_device_name_free_hint(void **hints)
{
	free(hints);
	return 0;
}
